"""Deliberately naive reference implementation of the audit contract.

Written straight from the specification text: no transaction journal, whole
state snapshots for rollback, per-byte dicts for reassembly.  Only used to
cross-check the fast implementation on small inputs.
"""
import copy

MAXN = 4611686018427387903
LEVELS = ("I", "H", "Z", "A")

WL = {
    "PADDING": ("I", "H", "Z", "A"),
    "PING": ("I", "H", "Z", "A"),
    "ACK": ("I", "H", "A"),
    "CRYPTO": ("I", "H", "A"),
    "STREAM": ("Z", "A"),
    "RESET_STREAM": ("Z", "A"),
    "STOP_SENDING": ("Z", "A"),
    "HANDSHAKE_DONE": (),
    "UNKNOWN": ("I", "H", "Z", "A"),
}


def replay(tr):
    cfg = tr["config"]
    early = cfg["early"]
    overlap = cfg["overlap"]
    bufmax = cfg["buffer_packets"]
    idle_ms = cfg["idle_ms"]
    limits = {"bidi": cfg["max_streams_bidi"], "uni": cfg["max_streams_uni"]}
    msd = cfg["max_stream_data"]
    max_data = cfg["max_data"]
    clim = cfg["crypto_limit"]
    sent = cfg["sent"]

    keys = {"I": "live", "H": "absent", "Z": "live" if early else "absent",
            "A": "absent"}
    queue = {lvl: [] for lvl in LEVELS}
    pnsets = {"I": set(), "H": set(), "A": set()}
    streams = {}
    crypto = {lvl: {"highest": 0, "bytes": {}, "contig": bytearray()}
              for lvl in ("I", "H", "A")}
    received_total = 0
    state = "open"
    code = at_ms = source = peer = None
    last_activity = 0
    out = []
    qcount = [0]

    def stream(sid):
        if sid not in streams:
            streams[sid] = {"highest": 0, "final_size": None, "reset": False,
                            "stopped": False, "bytes": {},
                            "delivered": bytearray()}
        return streams[sid]

    def drop_queue(lvl, reason, at):
        for (ei, pi, _ta, _pk) in queue[lvl]:
            out.append((ei, pi, "dropped", reason, at, None))
        qcount[0] -= len(queue[lvl])
        queue[lvl] = []

    def terminate(st, cd, at, src, peer_code):
        nonlocal state, code, at_ms, source, peer
        state = st
        code = cd
        at_ms = at
        source = src
        peer = peer_code
        for lvl in LEVELS:
            drop_queue(lvl, "CONNECTION_CLOSED", at)

    def res(ei, pi, status, reason, at, frame):
        out.append((ei, pi, status, reason, at, frame))

    def check_stream_dir(sid, kind):
        mod = sid % 4
        if kind == "STOP_SENDING":
            if mod != 0:
                return "STREAM_STATE_ERROR"
            if sid // 4 + 1 > limits["bidi"]:
                return "STREAM_LIMIT_ERROR"
            return None
        if mod not in (0, 2):
            return "STREAM_STATE_ERROR"
        if sid // 4 + 1 > limits["bidi" if mod == 0 else "uni"]:
            return "STREAM_LIMIT_ERROR"
        return None

    def process(ei, pi, pk, t):
        nonlocal state, code, at_ms, source, peer, received_total, last_activity
        lvl = pk["level"]
        pn = pk["pn"]
        frames = pk["frames"]
        space = "A" if lvl in ("Z", "A") else lvl
        if not pk["auth"]:
            res(ei, pi, "dropped", "AUTH", t, None)
            return
        if pn in pnsets[space]:
            res(ei, pi, "duplicate", "DUPLICATE", t, None)
            return
        if len(frames) == 0:
            res(ei, pi, "error", "FRAME_ENCODING_ERROR", t, None)
            terminate("closed", "FRAME_ENCODING_ERROR", t,
                      {"event": ei, "packet": pi, "frame": None}, None)
            return
        for fi, f in enumerate(frames):
            if f["type"] == "UNKNOWN":
                res(ei, pi, "error", "FRAME_ENCODING_ERROR", t, fi)
                terminate("closed", "FRAME_ENCODING_ERROR", t,
                          {"event": ei, "packet": pi, "frame": fi}, None)
                return
        for fi, f in enumerate(frames):
            allowed = WL[f["type"]]
            if f["type"] == "CLOSE" and not f["app"]:
                allowed = ("I", "H", "Z", "A")
            if lvl not in allowed:
                res(ei, pi, "error", "PROTOCOL_VIOLATION", t, fi)
                terminate("closed", "PROTOCOL_VIOLATION", t,
                          {"event": ei, "packet": pi, "frame": fi}, None)
                return
        saved = (copy.deepcopy(streams), copy.deepcopy(crypto),
                 received_total)
        close_fi = None
        for fi, f in enumerate(frames):
            ty = f["type"]
            err = None
            if ty in ("PADDING", "PING"):
                continue
            if ty == "ACK":
                rngs = f["ranges"]
                if not rngs:
                    err = "FRAME_ENCODING_ERROR"
                else:
                    prev = None
                    for lo, hi in rngs:
                        if lo > hi or (prev is not None and lo <= prev + 1):
                            err = "FRAME_ENCODING_ERROR"
                            break
                        prev = hi
                    if err is None:
                        for lo, hi in rngs:
                            ok = any(slo <= lo and hi <= shi
                                     for slo, shi in sent[space])
                            if not ok:
                                err = "PROTOCOL_VIOLATION"
                                break
            elif ty == "CRYPTO":
                off = f["offset"]
                data = bytes.fromhex(f["data_hex"])
                end = off + len(data)
                cs = crypto[lvl]
                if end > MAXN:
                    err = "FRAME_ENCODING_ERROR"
                elif end > clim:
                    err = "CRYPTO_BUFFER_EXCEEDED"
                else:
                    cs["highest"] = max(cs["highest"], end)
                    for i, b in enumerate(data):
                        p = off + i
                        if p in cs["bytes"]:
                            if cs["bytes"][p] != b and overlap == "reject":
                                err = "PROTOCOL_VIOLATION"
                                break
                        else:
                            cs["bytes"][p] = b
                    if err is None:
                        pos = len(cs["contig"])
                        while pos in cs["bytes"]:
                            cs["contig"].append(cs["bytes"][pos])
                            pos += 1
            elif ty == "STREAM":
                sid = f["id"]
                err = check_stream_dir(sid, ty)
                if err is None:
                    st = stream(sid)
                    off = f["offset"]
                    data = bytes.fromhex(f["data_hex"])
                    fin = f["fin"]
                    end = off + len(data)
                    if end > MAXN:
                        err = "FRAME_ENCODING_ERROR"
                    elif st["final_size"] is not None and (
                            end > st["final_size"] or (fin and end != st["final_size"])):
                        err = "FINAL_SIZE_ERROR"
                    elif fin and end < st["highest"]:
                        err = "FINAL_SIZE_ERROR"
                    elif end > msd:
                        err = "FLOW_CONTROL_ERROR"
                    elif received_total + max(0, end - st["highest"]) > max_data:
                        err = "FLOW_CONTROL_ERROR"
                    else:
                        if not st["reset"]:
                            for i, b in enumerate(data):
                                p = off + i
                                if p in st["bytes"]:
                                    if st["bytes"][p] != b and overlap == "reject":
                                        err = "PROTOCOL_VIOLATION"
                                        break
                                else:
                                    st["bytes"][p] = b
                        if err is None:
                            if end > st["highest"]:
                                received_total += end - st["highest"]
                                st["highest"] = end
                            if not st["reset"]:
                                pos = len(st["delivered"])
                                while pos in st["bytes"]:
                                    st["delivered"].append(st["bytes"][pos])
                                    pos += 1
                            if fin:
                                st["final_size"] = end
            elif ty == "RESET_STREAM":
                sid = f["id"]
                size = f["final_size"]
                err = check_stream_dir(sid, ty)
                if err is None:
                    st = stream(sid)
                    if st["final_size"] is not None and st["final_size"] != size:
                        err = "FINAL_SIZE_ERROR"
                    elif size < st["highest"]:
                        err = "FINAL_SIZE_ERROR"
                    elif size > msd:
                        err = "FLOW_CONTROL_ERROR"
                    elif received_total + max(0, size - st["highest"]) > max_data:
                        err = "FLOW_CONTROL_ERROR"
                    else:
                        if size > st["highest"]:
                            received_total += size - st["highest"]
                            st["highest"] = size
                        st["final_size"] = size
                        st["reset"] = True
            elif ty == "STOP_SENDING":
                sid = f["id"]
                err = check_stream_dir(sid, ty)
                if err is None:
                    st = stream(sid)
                    st["stopped"] = True
            elif ty == "CLOSE":
                close_fi = fi
                break
            if err is not None:
                streams, crypto2, received_total = saved[0], saved[1], saved[2]
                streams.clear(); streams.update(saved[0])
                for lvl2 in crypto:
                    crypto[lvl2] = saved[1][lvl2]
                res(ei, pi, "error", err, t, fi)
                terminate("closed", err, t,
                          {"event": ei, "packet": pi, "frame": fi}, None)
                return
        pnsets[space].add(pn)
        last_activity = t
        res(ei, pi, "accepted", "OK", t, None)
        if close_fi is not None:
            f = frames[close_fi]
            cd = "PEER_APPLICATION_CLOSE" if f["app"] else "PEER_TRANSPORT_CLOSE"
            terminate("closed", cd, t, {"event": ei, "packet": pi,
                                        "frame": close_fi}, f["code"])

    for ei, ev in enumerate(tr["events"]):
        t = ev["t"]
        if state == "open" and idle_ms and t >= last_activity + idle_ms:
            terminate("idle", "IDLE_TIMEOUT", last_activity + idle_ms,
                      {"event": ei, "packet": None, "frame": None}, None)
        if ev["op"] == "datagram":
            if state == "open":
                pkts = ev["packets"]
                layout = any(pk["level"] == "A" and i != len(pkts) - 1
                             for i, pk in enumerate(pkts))
                if layout:
                    for pi in range(len(pkts)):
                        res(ei, pi, "dropped", "LAYOUT", t, None)
                    continue
                for pi, pk in enumerate(pkts):
                    if state != "open":
                        res(ei, pi, "dropped", "CONNECTION_CLOSED", t, None)
                        continue
                    lvl = pk["level"]
                    if lvl == "I" and ev["bytes"] < 1200:
                        res(ei, pi, "dropped", "INITIAL_TOO_SMALL", t, None)
                        continue
                    if lvl == "Z" and not early:
                        res(ei, pi, "dropped", "EARLY_REJECTED", t, None)
                        continue
                    if keys[lvl] == "discarded":
                        res(ei, pi, "dropped", "KEYS_DISCARDED", t, None)
                        continue
                    if keys[lvl] == "absent":
                        if qcount[0] < bufmax:
                            queue[lvl].append((ei, pi, t, pk))
                            qcount[0] += 1
                        else:
                            res(ei, pi, "dropped", "BUFFER_FULL", t, None)
                        continue
                    process(ei, pi, pk, t)
            else:
                for pi in range(len(ev["packets"])):
                    res(ei, pi, "dropped", "CONNECTION_CLOSED", t, None)
            continue
        if state != "open":
            continue
        if ev["op"] == "key":
            lvl = ev["level"]
            if ev["action"] == "discard":
                keys[lvl] = "discarded"
                drop_queue(lvl, "KEYS_DISCARDED", t)
            else:
                if keys[lvl] == "absent":
                    keys[lvl] = "live"
                    items = queue[lvl]
                    queue[lvl] = []
                    qcount[0] -= len(items)
                    for (ei2, pi2, _ta, pk) in items:
                        if state != "open":
                            res(ei2, pi2, "dropped", "CONNECTION_CLOSED", t,
                                None)
                            continue
                        process(ei2, pi2, pk, t)
        # tick: nothing
    for lvl in LEVELS:
        for (ei, pi, ta, _pk) in queue[lvl]:
            res(ei, pi, "buffered", "NO_KEYS", ta, None)

    packets = [dict(event=ei, packet=pi, status=st, reason=rs, at_ms=at,
                    frame=fr)
               for (ei, pi, st, rs, at, fr) in sorted(out, key=lambda r: (r[0], r[1]))]
    if state == "open":
        conn = {"state": "open", "code": None, "at_ms": None, "source": None,
                "peer_code": None, "last_activity_ms": last_activity}
    else:
        conn = {"state": state, "code": code, "at_ms": at_ms, "source": source,
                "peer_code": peer, "last_activity_ms": last_activity}
    sl = []
    for sid in sorted(streams):
        st = streams[sid]
        sl.append({"id": sid, "highest": st["highest"],
                   "final_size": st["final_size"], "reset": st["reset"],
                   "stopped": st["stopped"],
                   "delivered_hex": bytes(st["delivered"]).hex()})
    cl = []
    for lvl in ("I", "H", "A"):
        cs = crypto[lvl]
        cl.append({"level": lvl, "highest": cs["highest"],
                   "contiguous_hex": bytes(cs["contig"]).hex()})
    return {"id": tr["id"], "packets": packets, "connection": conn,
            "keys": dict(keys), "received_total": received_total,
            "streams": sl, "crypto": cl}
PYEOF
cd /app && python3 -c "
import sys, json
sys.path.insert(0,'/workspace/tests')
import ref
doc=json.load(open('examples/basic.json'))
got={'version':1,'results':[ref.replay(t) for t in doc['traces']]}
exp=json.load(open('examples/basic.expected.json'))
print('ref MATCH' if got==exp else 'ref DIFF')
import itertools
def find(a,b,path=''):
    if type(a)!=type(b): print('type',path); return
    if isinstance(a,dict):
        for k in set(a)|set(b): find(a.get(k),b.get(k),path+'/'+str(k))
    elif isinstance(a,list) and len(a)!=len(b): print('len',path,len(a),len(b))
    elif isinstance(a,list):
        for i,(x,y) in enumerate(zip(a,b)): find(x,y,path+'/'+str(i))
    elif a!=b: print('diff',path,a,b)
find(got,exp)"
